package fraymus.workspace;
import org.json.*;
import java.util.*;

/** Resolves retained procedures against fresh user selections. Never installs executable handlers. */
final class Procedure044 {
 private final Domain044.Native api;
 Procedure044(Domain044.Native api){this.api=api;}
 JSONObject selected(JSONObject args)throws Exception{for(Object raw:api.call("/api/state",new JSONObject()).getJSONArray("procedures")){var p=(JSONObject)raw;if(p.getString("name").equals(args.getString("name"))&&p.getInt("version")==args.getInt("version"))return p;}throw new IllegalArgumentException("Choose an actual retained procedure name and version");}
 JSONObject prepare(JSONObject input)throws Exception{var p=selected(input.getJSONObject("args"));return new JSONObject().put("needsPerceptionFrame",p.getString("kind").equals("browser-perception-v1"));}
 JSONObject run(JSONObject input)throws Exception{SpatialScene.keys(input,"args","bindings","request");var provided=WorldFrames.copy(input.getJSONObject("args"));var p=selected(provided);String family=Domain044.familyFor(p.getString("kind")),request=input.optString("request","");var b=input.optJSONObject("bindings",new JSONObject());var defaults=p.optJSONObject("defaults",new JSONObject());var required=Requested044.fields(request,family);var args=WorldFrames.copy(provided);args.remove("kind");
  if(family.equals("workflow")){bindData(args,b);return new JSONObject().put("family","workflow").put("record",api.call("/api/workflows/reuse",args));}
  if(family.equals("world")||family.equals("pose")){var chosen=binding(b,family);for(String k:family.equals("world")?List.of("worldId","expectedRevision","expectedHash"):List.of("sceneId"))pin(args,k,chosen.get(k));if(ChatPolicy044.has(request,"displayed|selected target"))pin(args,"targets",chosen.get("targets"));for(String k:List.of("forceLimitN","torqueLimitNm")){Object original=defaults.opt(k);if(original==null)original=chosen.opt(k);if(args.has(k)&&original!=null&&!equal(args.get(k),original)&&!ChatPolicy044.has(request,k+"\\s*[=:]?\\s*"+java.util.regex.Pattern.quote(args.get(k).toString())+"\\b"))throw new IllegalArgumentException("Preserve retained "+k+" unless explicitly requested");}if(!request.isBlank())args.put("request",request);}
  if(family.equals("push")){var chosen=binding(b,"push");for(String k:List.of("sceneId","objectId","pusherId"))pin(args,k,chosen.get(k));for(String k:List.of("initialForceN","maxForceN"))if(!request.isBlank()&&args.has(k)&&defaults.has(k)&&!equal(args.get(k),defaults.get(k))&&!equal(args.opt(k),required.opt(k)))throw new IllegalArgumentException("Preserve retained "+k+" unless explicitly requested");for(String k:List.of("useActiveProfile","useContactController"))required.remove(k);if(!request.isBlank())args.put("request",request);}
  if(family.equals("map")){var chosen=provided.has("mapId")||provided.has("referenceId")?provided:binding(b,"mapping");for(String k:List.of("referenceId","mapId"))if(chosen.has(k))pin(args,k,chosen.get(k));if(chosen.has("mapId")&&required.keySet().stream().anyMatch(k->!Set.of("disturbanceNs","saveSkillName").contains(k)))throw new IllegalArgumentException("Compiled maps keep their immutable definition; select a reference image to change generation options");var options=args.optJSONObject("options",new JSONObject());for(String k:new ArrayList<>(args.keySet()))if(!Set.of("name","version","referenceId","mapId","options","disturbanceNs","saveSkillName").contains(k)){options.put(k,args.get(k));args.remove(k);}var retained=defaults.optJSONObject("options",new JSONObject());if(options.has("materials")&&retained.has("materials")&&!materialsEqual(options.getJSONArray("materials"),retained.getJSONArray("materials"))&&(!required.has("materials")||!materialsEqual(options.getJSONArray("materials"),required.getJSONArray("materials"))))throw new IllegalArgumentException("Preserve retained material values unless explicitly supplied in the request");var constraints=options.optJSONObject("constraints",new JSONObject());var original=retained.optJSONObject("constraints",new JSONObject());for(String k:constraints.keySet())if(original.has(k)&&!equal(constraints.get(k),original.get(k))&&!equal(constraints.get(k),required.optJSONObject("constraints",new JSONObject()).opt(k)))throw new IllegalArgumentException("Preserve retained global constraint "+k);var flat=WorldFrames.copy(required);for(String k:List.of("disturbanceNs","saveSkillName"))flat.remove(k);options=Requested044.preserve(options,flat);args.put("options",options);for(String k:List.of("disturbanceNs","saveSkillName"))if(required.has(k))args=Requested044.preserve(args,new JSONObject().put(k,required.get(k)));required=new JSONObject();}
  if(family.equals("space")){var def=args.optJSONObject("definition",new JSONObject());for(String k:new ArrayList<>(args.keySet()))if(!Set.of("name","version","definition","seed","saveSkillName").contains(k)){def.put(k,args.get(k));args.remove(k);}for(String k:new ArrayList<>(required.keySet()))if(!k.equals("saveSkillName")){if(args.has(k)){def.put(k,args.get(k));args.remove(k);}def=Requested044.preserve(def,new JSONObject().put(k,required.get(k)));}if(!def.isEmpty())args.put("definition",def);var rest=new JSONObject();if(required.has("saveSkillName"))rest.put("saveSkillName",required.get("saveSkillName"));required=rest;}
  if(family.equals("data"))bindData(args,b);
  if(family.equals("spatial")){var chosen=binding(b,"spatial");for(String k:List.of("sceneId","objectId"))pin(args,k,chosen.get(k));}
  if(family.equals("creation")&&!args.has("sourceArtifactId")&&p.optJSONObject("sourceRequirements",new JSONObject()).optBoolean("required"))Domain044.merge(args,binding(b,"creation"));
  if(family.equals("perception")){for(String k:provided.keySet())if(!Set.of("name","version","targetLabel","seconds","saveSkillName","frameId").contains(k))throw new IllegalArgumentException("Retained perception policy is immutable; only targetLabel, seconds and an actual current frame may change");if(defaults.optString("mode").equals("appearance")&&args.has("targetLabel")&&!args.getString("targetLabel").equals(defaults.getString("targetLabel")))throw new IllegalArgumentException("Retained taught appearance category cannot change");if(!args.has("frameId"))throw new IllegalArgumentException("Capture the actual browser frame before running this skill");}
  if(family.equals("goal")){var parameters=args.optJSONObject("parameters",new JSONObject());for(String k:List.of("angleDeg","friction","gravityMps2","massKg"))if(required.has(k)){parameters=Requested044.preserve(parameters,new JSONObject().put(k,required.get(k)));required.remove(k);}if(!parameters.isEmpty())args.put("parameters",parameters);}
  if(!request.isBlank()&&!required.has("saveSkillName")&&args.has("saveSkillName")&&!args.getString("saveSkillName").isBlank())throw new IllegalArgumentException("Saving a new procedure version must be requested");args=Requested044.preserve(args,required);
  if(family.equals("world")&&args.optBoolean("counterfactual045")&&ChatPolicy044.counterReview045(request))args.put("reviewCounterfactual045",true);
  return new JSONObject().put("family","goal").put("record",api.call("/api/procedures/run",args));
 }
 static void bindData(JSONObject args,JSONObject b){if(!args.has("datasetId")){var d=binding(b,"dataset");args.put("datasetId",d.getString("datasetId")).put("datasetVersion",d.getInt("version"));}}
 static JSONObject binding(JSONObject b,String k){var v=b.optJSONObject(k);if(v==null)throw new IllegalArgumentException("Choose a fresh "+k+" source in the app first");return WorldFrames.copy(v);}
 static boolean equal(Object a,Object b){return a!=null&&b!=null&&new JSONObject().put("v",a).similar(new JSONObject().put("v",b));}
 static void pin(JSONObject args,String key,Object value){if(args.has(key)&&!equal(args.get(key),value))throw new IllegalArgumentException("Selected source/role changed: "+key);args.put(key,value);}
 static boolean materialsEqual(JSONArray a,JSONArray b){var aa=new TreeMap<Integer,JSONObject>();var bb=new TreeMap<Integer,JSONObject>();for(Object raw:a){var m=Domain044.merge(new JSONObject().put("restitution",0).put("dragNsPerM",0),(JSONObject)raw);aa.put(m.getInt("tile"),m);}for(Object raw:b){var m=Domain044.merge(new JSONObject().put("restitution",0).put("dragNsPerM",0),(JSONObject)raw);bb.put(m.getInt("tile"),m);}return aa.keySet().equals(bb.keySet())&&aa.keySet().stream().allMatch(k->aa.get(k).similar(bb.get(k)));}
}
